def build(f,ny,nu,lag_inputs,use):
    d=pd.read_csv(f).iloc[::5]
    Q=d.reactive_power_pu.values; P=d.active_power_pu.values
    ins={'S':d.voltage_setpoint_pu.values,'V':d.voltage_pu.values,'th':d.bus_angle_rad.values,'P':P}
    N=len(Q); m=max(ny,nu)
    rows=[];y=[]
