import pandas as pd,numpy as np
from scipy.optimize import least_squares
from scipy.signal import lfilter
files=['train/'+f for f in ['A_vref_op1.csv','A_vref_op3.csv','A_amb_op1.csv','A_gentrip_op1.csv','A_load_op2.csv','A_line_op3.csv','A_amb_op2.csv']]
D=[]
for f in files:
    d=pd.read_csv(f).iloc[::5]
    th=d.bus_angle_rad.values; dt=0.005
    w=np.gradient(th,dt)
    D.append(dict(name=f,Q=d.reactive_power_pu.values,P=d.active_power_pu.values,V=d.voltage_pu.values,S=d.voltage_setpoint_pu.values,dt=dt,th=th,w=w))
def lag(u,K,T,dt):
    a=dt/T
    return lfilter([K*a],[1,-(1-a)],u-u[0])
def qm(p,x):
    Ka,Ta,Kb,Tb,Kw,Tw=p
    dt=x['dt']
    return lag(x['S'],Ka,Ta,dt)+lag(x['V'],Kb,Tb,dt)+lag(x['w'],Kw,Tw,dt)
def res(p): return np.concatenate([(x['Q']-x['Q'][0])-qm(p,x) for x in D])
best=None
for p0 in [[10,7,-12,14,0,1],[3,0.5,-3,0.5,1,0.5],[10,0.1,-10,0.1,0.1,0.5]]:
    sol=least_squares(res,p0,bounds=([-50,0.005,-50,0.005,-500,0.005],[50,20,50,20,500,20]))
    if best is None or sol.cost<best.cost: best=sol
print(np.round(best.x,4),np.sqrt(np.mean(best.fun**2)))
for x in D: print(x['name'], np.sqrt(np.mean(((x['Q']-x['Q'][0])-qm(best.x,x))**2)))

